<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><div class="page-head"><h1>Customers</h1><a class="button primary" href="<?= site_url('customers/create') ?>">Add Customer</a></div><div class="panel"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($customers as $c): ?><tr><td><?= esc($c['full_name']) ?></td><td><?= esc($c['email']) ?></td><td><?= esc($c['phone']??'—') ?></td><td><?= $c['is_active']?'Active':'Archived' ?></td><td><a href="<?= site_url('customers/'.$c['id'].'/edit') ?>">Edit</a><?php if($c['is_active']): ?><form class="inline" method="post" action="<?= site_url('customers/'.$c['id'].'/archive') ?>" onsubmit="return confirm('Archive this customer?')"><?= csrf_field() ?><button class="danger link">Archive</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?= $this->endSection() ?>
